// n8n Code node: normalize and clean text output

function cleanText(str) {
  if (!str) return '';

  // 1️⃣ Remove Spanish-style punctuation and common marks
  str = str.replace(/[¿¡!]/g, '');

  // 2️⃣ Remove long/short dashes, underscores, and similar characters
  str = str.replace(/[—–\-‐-‒_]+/g, ' ');

  // 3️⃣ Remove quotes, brackets, and miscellaneous symbols
  str = str.replace(/[“”"‘’'«»<>()[\]{}]/g, '');

  // 4️⃣ Remove multiple punctuation sequences like "..." or "!!"
  str = str.replace(/[.,;:…]+/g, ' ');

  // 5️⃣ Normalize accents (optional — keep Spanish characters if you prefer)
  str = str.normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  // 6️⃣ Collapse extra whitespace and trim
  str = str.replace(/\s+/g, ' ').trim();

  return str;
}

// 🔧 Apply to each item (or modify for your data field)
return items.map(item => {
  const raw = item.json.agent_output || item.json.text || '';
  const cleaned = cleanText(raw);
  return {
    json: {
      ...item.json,
      cleaned_output: cleaned
    }
  };
});
